import {formatValidationError} from './registry.js';

describe('Tool validation errors', () => {
  it('preserves field paths from both validator error formats (spec: specs/hal-engine-tool-input-validation/spec.md#2)', () => {
    const errors = [
      {dataPath: '.location', keyword: 'type', message: 'should be number'},
      {dataPath: '.units', keyword: 'enum', message: 'should be equal to one of the allowed values'},
      {instancePath: '/location', keyword: 'type', message: 'must be number'},
      {instancePath: '/units', keyword: 'enum', message: 'must be equal to one of the allowed values'},
    ];
    expect(errors.map(formatValidationError)).toEqual([
      '.location type: should be number',
      '.units enum: should be equal to one of the allowed values',
      '/location type: must be number',
      '/units enum: must be equal to one of the allowed values',
    ]);
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.error-path.test.ts --runInBand"

